	def findMedian(self, A):

        # Also check:
        # https://www.scaler.com/academy/mentee-dashboard/class/25095/homework/problems/357?navref=cl_tt_lst_nm

        def findCount(ar, num):
            # return upper bound of the number num in ar
            # UB: smallest no. greater than num
            if num < ar[0]: return 0
            if num > ar[-1]: return len(ar)

            i = 0
            j = len(ar)-1
            ans  = 0
            while i <= j:
                mid = (i+j) // 2
                if ar[mid] <= num:
                    ans = mid
                    i = mid + 1
                else:
                    j = mid - 1
            return ans + 1

        i = float('inf')
        j = float('-inf')
        for row in A:
            i = min(i, row[0])
            j = max(j, row[-1])

        minNumsGreaterCount = (len(A)*len(A[0])) // 2 + 1

        ans = -1
        while i <= j:
            mid = (i+j) // 2

            c = 0
            for row in A:
                c += findCount(row, mid)

            if c >= minNumsGreaterCount:
                ans = mid
                j = mid - 1
            else:
                i = mid + 1

        return ans

