    # @param A : tuple of integers
    # @param B : integer
    # @return an integer
    def search(self, A, B):

        # There's a point in the array from where 
        # the array re-starts as a sorted series
        # That point is the pivot which divides the array 
        # into two different sorted series.
        # Find the pivot using BS, then divide the array into 
        # two sub-arrays A[:pivot] and A[pivot:] and do BS again 
        # to find the target element

        def findPivot(A):
            lo = 0
            hi = len(A) - 1  
            while lo <= hi:
                mid = (lo+hi) // 2

                if mid == 0 or mid == len(A)-1:
                    return mid

                if A[mid] > A[mid-1] and A[mid] > A[mid+1]:
                    return mid

                if A[mid] < A[lo]:
                    hi = mid - 1
                else:
                    lo = mid+1


        def binarySearch(ar, target, start, end):
            lo = start
            hi = end
            while lo <= hi:
                mid = (lo+hi) // 2

                if ar[mid] == target:
                    return mid

                if ar[mid] < target:
                    lo = mid + 1
                else:
                    hi = mid - 1

            return -1


        pivot = findPivot(A)
        res1 = binarySearch(A, B, 0, pivot)
        res2 = binarySearch(A, B, pivot+1, len(A)-1)

        if res1 != -1:
            return res1
        else:
            return res2

