    # @param A : integer
    # @param B : integer
    # @param C : integer
    # @return an integer
    def solve(self, A, B, C):

        def gcd(a, b):
            if b == 0:
                return a
            return gcd(b, a%b)

        def lcm(a, b):
            return (a // gcd(a,b)) * b

        def findMagicalNo(x, b, c):
            return x // b + x // c - x // lcm(b,c)


        i = 1
        j = min(B, C) * A
        ans = -1
        while i <= j:

            mid = (i+j)//2

            res = findMagicalNo(mid, B, C)

            if res > A:
                j = mid-1
            elif res < A:
                i = mid+1
            else:
                ans = mid
                j = mid-1

        return ans % 1000000007

