                self.head = Node(value)
                self.head.next = temp

        i = 1
        temp = self.head
        while i != position-1:
            i+=1
            temp = temp.next
            if not temp: 
                break

        if not temp:
            return
        else:
            tempNext = temp.next
            newNode = Node(value)
            temp.next = newNode
            newNode.next = tempNext


    def delete_node(self, position):
        if position == 1:
            if self.head:
                temp = self.head
                self.head = self.head.next
                return temp.val

        i = 1
        temp = self.head
        while i != position-1:
            i+=1
            temp = temp.next
            if not temp: 
                break

        if not temp:
            return
        elif temp.next:
            deleted = temp.next
            temp.next = temp.next.next
            return deleted.val

