class Solution:
    # @param A : list of integers
    # @return an integer

    def largestRectangleArea(self, A):
        if len(A) == 1: return A[0]

        def nextSmaller(A, dir):
            NS = []
            stack = []
            i = 0 if dir == 'L' else len(A)-1
            while True:
                while stack and A[stack[-1]] >= A[i]:
                    stack.pop()
                if not stack:
                    NS.append(-1)
                else:
                    NS.append(stack[-1])
                stack.append(i)

                if dir == 'L':
                    i += 1
                    if i == len(A): break
                else:
                    i -= 1
                    if i == -1: break

            return NS if dir == 'L' else NS[::-1]

        NSL = nextSmaller(A, 'L')
        NSR = nextSmaller(A, 'R')
        # Here NS array contains count of vertical bars that 
        # contribute to the area

        # print(NSL, NSR)
        # return

        ans = float('-inf')
        for i in range(len(A)):

            if NSR[i] == -1 and NSL[i] == -1:
                ans = max(ans, A[i] * len(A))
            elif NSR[i] != -1 and NSL[i] != -1:
                curr = (NSR[i] - NSL[i] - 1) * A[i]
                ans = max(ans, curr)
            else:

                if NSL[i] == -1:
                    curr = NSR[i] * A[i]
                    ans = max(ans, curr)   

                if NSR[i] == -1:
                    curr = (len(A) - NSL[i] - 1) * A[i] # => (y-x+1) check notes
                    ans = max(ans, curr)

        return ans

