class MinStack:
    # @param x, an integer
    # @return an integer
    def __init__(self):
        self.stack = []
        self.min_stack = []

    # @param stack, a list 
    def isempty(self, stack):
        if len(stack) == 0:
            return True
        else:
            return False

    # @param x, an integer
    def push(self, x):
        #edge case : handle duplicates <= sign
        # if stack empty push x
        if len(self.min_stack) == 0 or x <= self.min_stack[-1]:
            self.min_stack.append(x)
                #can test full in case of static stack
        self.stack.append(x)

    # @return nothing
    def pop(self):
        if self.isempty(self.stack):
            return
        else:
            x = self.stack.pop()
            if x <= self.min_stack[-1]:
                self.min_stack.pop()
            return x

    # @return an integer
    def top(self):
        if len(self.stack) == 0:
            return -1
        return self.stack[-1]

    # @return an integer
    def getMin(self):
        if len(self.min_stack) == 0:
            return -1
        return self.min_stack[-1]

class Solution:
    # @param A : string
    # @return a strings
    def solve(self, A):

        res = ''
        stack = []
        for ch in A:

            if ch == '(':
                stack.append(ch)

            elif ch == ')':
                while stack[-1] != '(':
                    res += stack.pop()
                stack.pop()

            elif ch == '^':
                while stack and stack[-1] == '^':
                    res += stack.pop()
                stack.append(ch)

            elif ch in '/*':

                while stack and stack[-1] in '^/*':
                    res += stack.pop()

                stack.append(ch)

            elif ch in '+-':

                while stack and stack[-1] in '^/*+-':
                    res += stack.pop()

                stack.append(ch)

            else:
                res += ch

        while stack:
            res += stack.pop()

        return res

