                if stack[-1] in '+-*/':
                    stack.pop()
                    stack.pop()
                else:
                    return 1

        return 0

class Solution:
    # @param A : string
    # @param B : string
    # @return an integer
    def solve(self, A, B):

        # - - = +
        # + + = +
        # - + = -

        evalSigns = lambda a, b: '-' if a != b else '+'

        def evaluate(A):
            res = []
            i = 0
            currSign = ['+']
            posBracket = []

            if A[0] not in ['-', '+']:
                if A[0] != '(':
                    res.append('+' + A[0])
                i+=1

            while i < len(A):
                if A[i] == '+' or A[i] == '-':
                    if A[i+1] == '(':
                        currSign.append(evalSigns(A[i], currSign[-1]))
                    else:
                        sign = evalSigns(A[i], currSign[-1])
                        res.append(sign + A[i+1])
                    i+=1
                elif A[i] == '(':
                    posBracket.append('(')
                elif A[i] == ')':
                    if posBracket:
                        posBracket.pop()
                    else:
                        currSign.pop()
                        if not currSign:
                            currSign = ['+']
                else:
                    res.append(currSign[-1] + A[i])
                i+=1

            return res

        def sortExpression(A):
            A.sort(key=lambda x:x[1])
            return ''.join(A)

        A = sortExpression( evaluate(A) )
        B = sortExpression( evaluate(B) )

        # print(A, B)

        return 1 if A == B else 0

