class Solution:
    # @param A : string
    # @return a strings
    def solve(self, A):
        res = ''
        stack = []
        for ch in A:

            if ch == '(':
                stack.append(ch)

            elif ch == ')':
                while stack[-1] != '(':
                    res += stack.pop()
                stack.pop()

            elif ch == '^':
                while stack and stack[-1] == '^':
                    res += stack.pop()
                stack.append(ch)

            elif ch in '/*':

                while stack and stack[-1] in '^/*':
                    res += stack.pop()

                stack.append(ch)

            elif ch in '+-':

                while stack and stack[-1] in '^/*+-':
                    res += stack.pop()

                stack.append(ch)

            else:
                res += ch

        while stack:
            res += stack.pop()

        return res

class Solution:
    # @param A : list of list of integers
    # @return an integer
    def solve(self, A):

        prefCol = [[0 for _ in range(len(A[0]))] for _ in range(len(A))]

        for c in range(len(A[0])):
            prefCol[0][c] = A[0][c]

        for c in range(len(A[0])):
            for r in range(1, len(A)):
                if A[r][c] == 0:
                    prefCol[r][c] = A[r][c]
                else:
                    prefCol[r][c] = prefCol[r-1][c] + 1

        ans = float('-inf')
        for row in prefCol:
            ans = max(ans, self.largestRectangleArea(row))

        return ans

    def largestRectangleArea(self, A):
        if len(A) == 1: return A[0]

        def nextSmaller(A, dir):
            NS = []
            stack = []
            i = 0 if dir == 'L' else len(A)-1
            while True:
                while stack and A[stack[-1]] >= A[i]:
                    stack.pop()
                if not stack:
                    NS.append(-1)
                else:
                    NS.append(stack[-1])
                stack.append(i)

                if dir == 'L':
                    i += 1
                    if i == len(A): break
                else:
                    i -= 1
                    if i == -1: break

            return NS if dir == 'L' else NS[::-1]

        NSL = nextSmaller(A, 'L')
        NSR = nextSmaller(A, 'R')

        # print(NSL, NSR)
        # return

        ans = float('-inf')
        for i in range(len(A)):

            if NSR[i] == -1 and NSL[i] == -1:
                ans = max(ans, A[i] * len(A))
            elif NSR[i] != -1 and NSL[i] != -1:
                curr = (NSR[i] - NSL[i] - 1) * A[i]
                ans = max(ans, curr)
            else:

                if NSL[i] == -1:
                    curr = NSR[i] * A[i]
                    ans = max(ans, curr)   

                if NSR[i] == -1:
                    curr = (len(A) - NSL[i] - 1) * A[i]
                    ans = max(ans, curr)

        return ans
